def answer_man_on_right_of_net(image):
    image_patch = ImagePatch(image)
    men_patches = image_patch.find("man")
    net_patches = image_patch.find("net")

    if not men_patches or not net_patches:
        return "No man or net found in the image."

    men_patches.sort(key=lambda man: man.left)
    net_leftmost = min(net_patches, key=lambda net: net.left)

    for man in men_patches:
        if man.right > net_leftmost.left:
            return "Yes"

    return "No"

